# Generated by build.py from recipe.yml for recipe surl-keep-the-server-log-for-a-failed-run. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.csv'), "id,total`n1,40`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tests.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The tests of a CI run: the report over HTTPS with a password, then with a token, then`n# over FTPS; the first failure ends the run with curl's exit code.`n# Usage: sh tests.sh <https port> <ftps port> <ftps password>`nset -e`ncurl -sSf --cacert server.pem -u app:s3cret -o /dev/null `"https://127.0.0.1:`$1/report.csv`"`ncurl -sSf --cacert server.pem --oauth2-bearer tok-7f3a9c -o /dev/null `"https://127.0.0.1:`$1/report.csv`"`ncurl -sSf --cacert server.pem -u `"app:`$3`" -o /dev/null `"ftps://127.0.0.1:`$2/report.csv`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ci-step.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# A CI step: run the tests; if they fail, keep surl's trace in ci-logs/ for the job to`n# upload, and fail with the tests' exit code. surl has already withheld the passwords and`n# tokens of HTTPS and FTPS from the trace.`n# Usage: sh ci-step.sh <test command> [<argument>...]`n`"`$@`" && exit 0`nstatus=`$?`n# surl traces an exchange's last lines a moment after its client has gone: wait, at most 10 s,`n# until every exchange the trace opened has ended.`ni=0; until [ `"`$(grep -c 'Exchange [0-9]* opened: ' trace.txt)`" -eq `"`$(grep -c 'Exchange [0-9]* ended; ' trace.txt)`" ]; do i=`$((i+1)); [ `$i -ge 100 ] && break; sleep 0.1; done`nmkdir -p ci-logs`ncp trace.txt ci-logs/trace.txt`nexit `"`$status`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'drop-received.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Print a trace without the bytes clients sent: no user names, paths or other client data.`n# After a `"<= Recv data`" line come the bytes a client sent, one offset-led line each, up to`n# the next line that starts with an exchange number. Drop those bytes; keep everything else.`n# Usage: sh drop-received.sh <trace file>`nawk '/^#[0-9]+ <= Recv data/ { print; skip = 1; next }`n     /^#[0-9]+ / { skip = 0 }`n     !skip' `"`$1`"`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--trace-ascii', 'trace.txt', '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--user', 'app:s3cret', '--user', ':tok-7f3a9c', 'https://127.0.0.1:8080/', 'ftps://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh ci-step.sh sh tests.sh 8080 8081 guess } finally { Stop-Process $server0 }
